import ui_adapter.adapter.UIActionAdapter;
import ui_adapter.model.Action;
import ui_adapter.model.Selector;
import ui_adapter.model.Action.Type;
import ui_adapter.model.TestRunResult;
import ui_adapter.model.ActionResult;

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        System.out.println("Starting UI Action Adapter Demo...");

        // 1. Define the actions to execute
        List<Action> actions = new ArrayList<>();

        // Action: Navigate to Google
        actions.add(new Action(
            Type.NAVIGATE, 
            null, 
            "https://www.google.com"
        ));

        // Action: Confirm search box is visible (using CSS selector for textarea)
        actions.add(new Action(
            Type.WAIT_FOR_VISIBLE,
            new Selector(Selector.Type.CSS, "textarea[name='q']"),
            null
        ));

        // Action: Type "Playwright Java"
        actions.add(new Action(
            Type.TYPE,
            new Selector(Selector.Type.CSS, "textarea[name='q']"),
            "Playwright Java"
        ));

        // Action: Click Google Search (using the 'btnK' button often found in the dropdown or main area)
        // Note: Google's home page structure changes often, so this is a best-effort example.
        // We often need to click outside or hit enter, but let's try a simple click logic or verify text instead for stability.
        actions.add(new Action(
             Type.ASSERT_VISIBLE,
             new Selector(Selector.Type.CSS, "img[alt='Google']"), 
             null
        ));

        // Action: Take a screenshot
        actions.add(new Action(
            Type.SCREENSHOT,
            null,
            null
        ));

        // 2. Instantiate the Adapter
        UIActionAdapter adapter = new UIActionAdapter();

        // 3. Run the actions
        TestRunResult result = adapter.runActions(actions);

        // 4. Print results
        System.out.println("--------------------------------------------------");
        System.out.println("Test Run Success: " + result.isSuccess());
        if (!result.isSuccess()) {
            System.err.println("Error: " + result.getErrorMessage());
        }

        System.out.println("Step Results:");
        for (ActionResult step : result.getStepResults()) {
            System.out.printf("[%s] %s%n", step.getStatus(), step.getMessage());
            if (step.getScreenshotPath() != null) {
                System.out.println("   Screenshot: " + step.getScreenshotPath());
            }
        }
        System.out.println("--------------------------------------------------");
    }
}

import ui_adapter.adapter.UIActionAdapter;
import ui_adapter.agent.LlmAgent;
import ui_adapter.agent.SimpleRuleAgent;
import ui_adapter.agent.TestAgent;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.TestCase;
import ui_adapter.testcase.ExcelTestCaseLoader;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        // Usage:
        //   java Main <excelFilePath> [testCaseKey]
        // If omitted, falls back to the existing hard-coded goal below.

        TestAgent agent;

        if (args != null && args.length >= 1) {
            try {
                Path excel = Paths.get(args[0]);
                String key = args.length >= 2 ? args[1] : null;

                ExcelTestCaseLoader loader = new ExcelTestCaseLoader();
                List<TestCase> cases = loader.load(excel);
                if (cases.isEmpty()) {
                    throw new IllegalStateException("No test cases found in: " + excel);
                }

                TestCase selected;
                if (key != null && !key.isBlank()) {
                    selected = cases.stream()
                            .filter(tc -> key.equalsIgnoreCase(tc.getKey()))
                            .findFirst()
                            .orElseThrow(() -> new IllegalArgumentException("Test case key not found: " + key));
                } else {
                    selected = cases.get(0);
                }

                agent = new LlmAgent(selected.toGoalString());
            } catch (Exception e) {
                throw new RuntimeException("Failed to load test case from Excel: " + e.getMessage(), e);
            }
        } else {
            // Fallback to a hard-coded goal if no Excel is provided
            agent = new LlmAgent(
                    "Test Case: Verify Microsoft SSO Login and Bot Navigation – RPA Dashboard QA\n" +
                            "\n" +
                            "Objective:\n" +
                            "Validate that a user can access the RPA Dashboard QA environment, complete Microsoft SSO authentication, and navigate to a specific bot details page.\n" +
                            "\n" +
                            "Test Steps:\n" +
                            "1. Open a web browser and navigate to https://dashboard-qa.000-rpa-np.centralus.azr.sysco.net/ and MAXIMIZE the WINDOW\n" +
                            "2. Verify a version update popup is displayed and close it\n" +
                            "3. Click Login and complete SSO\n" +
                            "...\n"
            );
        }

        List<ActionResult> results = new ArrayList<>();
        ActionResult lastResult = null;

        try (UIActionAdapter adapter = new UIActionAdapter()) {
            while (!agent.isTestComplete()) {
                Action action = agent.nextAction(lastResult);
                if (action == null) {
                    break;
                }

                lastResult = adapter.execute(action);
                results.add(lastResult);
            }
        }

        agent.onTestEnd(results);

        for (ActionResult r : results) {
            System.out.printf("[%s] %s%n", r.getStatus(), r.getMessage());
            if (r.getScreenshotPath() != null) {
                System.out.println("  Screenshot: " + r.getScreenshotPath());
            }
        }
    }
}

